//! Cross-language-comparable benchmark: reads the SHARED corpora from
//! bench/corpus/ (generated by bench/gen_corpus.py) so all four languages
//! measure byte-identical inputs. Prints ns/leaf per strategy, in the same
//! layout as cpp/bench/corpus_bench.cpp.
//!
//! Usage: cargo run --release --bin bench [corpus_dir] [strategy...]   (default: ../bench/corpus, all)

use mathparser::{all_evaluators, with_big_stack, Evaluator};
use std::time::Instant;

const SIZES: [usize; 4] = [10, 100, 1000, 10000];

fn load(dir: &str, n: usize) -> Vec<String> {
    let path = format!("{}/n{}.txt", dir, n);
    match std::fs::read_to_string(&path) {
        Ok(s) => s.lines().filter(|l| !l.is_empty()).map(str::to_owned).collect(),
        Err(_) => Vec::new(),
    }
}

fn best_ns(reps: usize, mut f: impl FnMut()) -> f64 {
    let mut best = f64::INFINITY;
    for _ in 0..reps {
        let t0 = Instant::now();
        f();
        best = best.min(t0.elapsed().as_nanos() as f64);
    }
    best
}

fn run(dir: String, only: Vec<String>) -> i32 {
    let mut corpora = Vec::new();
    for &n in &SIZES {
        let c = load(&dir, n);
        if c.is_empty() {
            println!("error: empty/missing corpus n{} in {} (run: python3 bench/gen_corpus.py)", n, dir);
            return 1;
        }
        corpora.push(c);
    }
    println!("== Rust: shared-corpus benchmark ==\n");
    println!("{:<26}{:>12}{:>12}{:>12}{:>12}", "strategy", "n=10", "n=100", "n=1000", "n=10000");
    println!("{}", "-".repeat(26 + 48));
    let mut sink = 0u64;
    for ev in all_evaluators().iter_mut() {
        if !only.is_empty() && !only.iter().any(|n| n == ev.name()) { continue; }
        print!("{:<26}", ev.name());
        for (i, &n) in SIZES.iter().enumerate() {
            let corpus = &corpora[i];
            let reps = if n <= 1000 { 5 } else { 3 };
            let ns = best_ns(reps, || {
                let mut acc = 0.0f64;
                for e in corpus {
                    acc += ev.eval(e, None).unwrap_or(f64::NAN);
                }
                sink = sink.wrapping_add(acc as u64);
            });
            print!("{:>12.1}", ns / corpus.len() as f64 / n as f64);
        }
        println!();
    }
    std::hint::black_box(sink);
    0
}

fn main() {
    let mut args = std::env::args().skip(1);
    let dir = args.next().unwrap_or_else(|| "../bench/corpus".to_string());
    let dir = if std::path::Path::new(&dir).is_dir() || dir != "../bench/corpus" { dir } else { "bench/corpus".to_string() };
    let only: Vec<String> = args.collect(); // optional: strategy names to run
    std::process::exit(with_big_stack(move || run(dir, only)));
}

#[allow(dead_code)]
fn _assert_object_safe(_: &dyn Evaluator) {}
